CREATE TABLE runtime_command (id uuid PRIMARY KEY, payload_hash text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'ACCEPTED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE run_root (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, version_id uuid NOT NULL, bundle_hash text NOT NULL, spec jsonb NOT NULL, dependencies jsonb NOT NULL, input jsonb NOT NULL, status text NOT NULL DEFAULT 'QUEUED', output jsonb, error_code text, event_seq bigint NOT NULL DEFAULT 0, model_calls integer NOT NULL DEFAULT 0, tool_calls integer NOT NULL DEFAULT 0, tokens bigint NOT NULL DEFAULT 0, cost_status text NOT NULL DEFAULT 'UNPRICED_VALIDATION', started_at timestamptz, deadline timestamptz, finished_at timestamptz, checkpoint_id text);
CREATE TABLE invocation (id text PRIMARY KEY, run_id uuid REFERENCES run_root, parent_id text, node_id text NOT NULL, kind text NOT NULL, version_id text, input_hash text NOT NULL, input jsonb NOT NULL, output jsonb, status text NOT NULL DEFAULT 'RUNNING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operation_receipt (operation_key text PRIMARY KEY, run_id uuid REFERENCES run_root, input_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_decision (decision_key text PRIMARY KEY, run_id uuid REFERENCES run_root, input_hash text NOT NULL, response jsonb, state text NOT NULL DEFAULT 'RESERVED', usage jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE execution_event (run_id uuid REFERENCES run_root, seq bigint NOT NULL, event_id text NOT NULL UNIQUE, invocation_id text, node_id text, attempt_id text NOT NULL, type text NOT NULL, commit_status text NOT NULL, checkpoint_ref text, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,seq));
CREATE TABLE run_projection (run_id uuid PRIMARY KEY REFERENCES run_root, checkpoint_id text NOT NULL, snapshot jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
